    BaniLine(id = "chandi-di-vaar-131", gurmukhi = "ਕੋਪਰ ਚੂਰ ਚਵਾਣੀ; ਲਥੀ ਕਰਗ ਲੈ ॥", transliteration = "kopar choor chvaanee; lthee karag lai ||", translation = "It broke the skull and face into pieces and pierced through the skeleton.", hindi = "कोपर चूर चवाणी; लथी करग लै ॥", punjabi = "(ਉਹ ਤਲਵਾਰ ਦੈਂਤ ਦੀ) ਖੋਪਰੀ ਅਤੇ ਮੂੰਹ ਨੂੰ ਚੂਰ-ਚੂਰ ਕਰਦੀ ਪਿੰਜਰ ('ਕਰਗ') ਤਕ ਧਸ ਗਈ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "chandi-di-vaar-132", gurmukhi = "ਪਾਖਰ ਤੁਰਾ ਪਲਾਣੀ; ਰੜਕੀ ਧਰਤ ਜਾਇ ॥", transliteration = "paakhar turaa plaanee; rarkee dharat jaai ||", translation = "And it further pierced through the saddle and caparison of the horse, and struck on the earth supported by the Bull (Dhaul).", hindi = "पाखर तुरा पलाणी; रड़की धरत जाइ ॥", punjabi = "(ਫਿਰ) (ਘੋੜੇ ਉਪਰ ਪਾਈ ਹੋਈ ਲੋਹੇ ਦੀ) ਝੁਲ ਅਤੇ ਕਾਠੀ (ਨੂੰ ਚੀਰਦੀ ਹੋਈ) ਧਰਤੀ ਉਤੇ ਜਾ ਵਜੀ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "chandi-di-vaar-133", gurmukhi = "ਲੈਦੀ ਅਘਾ ਸਿਧਾਣੀ; ਸਿੰਗਾਂ ਧਉਲ ਦਿਆਂ ॥", transliteration = "laidee aghaa sidhaanee; singaan dhaul diaan ||", translation = "It moved further and struck the horns of the Bull.", hindi = "लैदी अघा सिधाणी; सिंगां धउल दिआं ॥", punjabi = "(ਉਥੋਂ) ਲਹਿੰਦੀ ਹੋਈ (ਧਰਤੀ ਨੂੰ ਚੁਕੀ ਖੜੇ) ਬਲਦ ਦੇ ਸਿੰਗਾਂ ਤਕ ਜਾ ਪਹੁੰਚੀ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "chandi-di-vaar-134", gurmukhi = "ਕੂਰਮ ਸਿਰ ਲਹਿਲਾਣੀ; ਦੁਸਮਨ ਮਾਰਿ ਕੈ ॥", transliteration = "kooram sir lhilaanee; dusaman maar kai ||", translation = "Then it struck on the Tortoise supporting the Bull and thus killing the enemy.", hindi = "कूरम सिर लहिलाणी; दुसमन मारि कै ॥", punjabi = "(ਇਸ ਤਰ੍ਹਾਂ) ਦੁਸ਼ਮਨ ਨੂੰ ਮਾਰ ਕੇ ਕਛੂਏ ਦੇ ਸਿਰ ਵਿਚ ਚਮਕੀ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "chandi-di-vaar-135", gurmukhi = "ਵਢੇ ਗਨ ਤਿਖਾਣੀ; ਮੂਏ ਖੇਤ ਵਿਚ ॥", transliteration = "vadhe gan tikhaanee; mooe khet vich ||", translation = "The demons are lying dead in the battlefield like the pieces of wood sawed by the carpenter.", hindi = "वढे गन तिखाणी; मूए खेत विच ॥", punjabi = "(ਦੈਂਤ ਇਸ ਤਰ੍ਹਾਂ) ਯੁੱਧ-ਭੂਮੀ ਵਿਚ ਮਰੇ ਪਏ ਸਨ (ਜਿਵੇਂ) ਤਿਖਾਣ ਨੇ (ਲਕੜੀ ਦੇ) ਮੋਛੇ ਵੱਢ ਦੇ (ਸੁਟੇ ਹਨ)।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "chandi-di-vaar-136", gurmukhi = "ਰਣ ਵਿਚ ਘਤੀ ਘਾਣੀ; ਲੋਹੂ ਮਿਝ ਦੀ ॥", transliteration = "ran vich ghtee ghaanee; lohoo mijh dee ||", translation = "The press of blood and marrow has been set in motion in the battlefield.", hindi = "रण विच घती घाणी; लोहू मिझ दी ॥", punjabi = "ਰਣ-ਭੂਮੀ ਵਿਚ ਲਹੂ ਅਤੇ ਮਿਝ ਦੀ ਘਾਣੀ ਬਣੀ ਪਈ ਸੀ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "chandi-di-vaar-137", gurmukhi = "ਚਾਰੇ ਜੁਗ ਕਹਾਣੀ; ਚਲਗ ਤੇਗ ਦੀ ॥", transliteration = "chaare jug khaanee; chalag teg dee ||", translation = "The story of the sword will be related in all the four ages.", hindi = "चारे जुग कहाणी; चलग तेग दी ॥", punjabi = "(ਦੇਵੀ ਦੀ) ਤਲਵਾਰ ਦੀ ਕਹਾਣੀ ਚੌਂਹਾਂ ਯੁਗਾਂ ਤਕ ਚਲੇਗੀ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "chandi-di-vaar-138", gurmukhi = "ਬਿਧਣ ਖੇਤ ਵਿਹਾਣੀ; ਮਹਖੇ ਦੈਤ ਨੂੰ ॥੧੯॥", transliteration = "bidhan khet vihaanee; mahkhe dait noon ||19||", translation = "On the demon Mahisha the period of agony occurred in the battlefield.19.", hindi = "बिधण खेत विहाणी; महखे दैत नूं ॥१९॥", punjabi = "ਮਹਿਖਾਸੁਰ ਨੂੰ ਯੁੱਧ-ਭੂਮੀ ਵਿਚ ਦੁਖਦਾਇਕ ਸਮਾਂ (ਬਿੱਧਣ) ਕਟਣਾ ਪਿਆ ॥੧੯॥", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "chandi-di-vaar-139", gurmukhi = "ਇਤੀ ਮਹਖਾਸੁਰ ਦੈਤ ਮਾਰੇ ਦੁਰਗਾ ਆਇਆ ॥", transliteration = "itee mahkhaasur dait maare durgaa aaiaa ||", translation = "In this way the demon Mahishasura was killed on the arrival of Durga.", hindi = "इती महखासुर दैत मारे दुरगा आइआ ॥", punjabi = "ਇਸ ਤਰ੍ਹਾਂ ਮਹਿਖਾਸੁਰ ਦੈਂਤ ਨੂੰ ਮਾਰ ਕੇ ਦੁਰਗਾ ਆ ਗਈ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "chandi-di-vaar-140", gurmukhi = "ਚਉਦਹ ਲੋਕਾਂ ਰਾਣੀ ਸਿੰਘ ਨਚਾਇਆ ॥", transliteration = "chaudah lokaan raanee singh nchaaiaa ||", translation = "The queen caused the lion to dance in the fourteen worlds.", hindi = "चउदह लोकां राणी सिंघ नचाइआ ॥", punjabi = "ਚੌਦਾਂ ਲੋਕਾਂ ਦੀ ਰਾਣੀ (ਦੇਵੀ ਨੇ ਪ੍ਰਸੰਨ ਹੋ ਕੇ ਆਪਣੇ ਵਾਹਨ) ਸ਼ੇਰ ਨੂੰ ਨਚਾਇਆ। ਦੇਵੀ ਦੁਰਗਾ ਨੇ ਚਉਦਹ ਲੋਕਾਂ ਰਾਣੀ ਸਿੰਘ ਨਚਾਇਆ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "chandi-di-vaar-141", gurmukhi = "ਮਾਰੇ ਬੀਰ ਜਟਾਣੀ; ਦਲ ਵਿਚ ਅਗਲੇ ॥", transliteration = "maare beer jtaanee; dal vich agle ||", translation = "She killed a great number of brave demons with matted locks in the battlefield.", hindi = "मारे बीर जटाणी; दल विच अगले ॥", punjabi = "(ਦੈਂਤਾਂ ਦੇ) ਦਲਾਂ ਵਿਚੋਂ ਬਹੁਤ ਸਾਰੇ ਜਟਾਧਾਰੀ ਵੀਰ (ਦੈਂਤਾਂ ਨੂੰ) ਦਲ ਵਿਚ ਮਾਰ ਦਿੱਤਾ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "chandi-di-vaar-142", gurmukhi = "ਮੰਗਨ ਨਾਹੀ ਪਾਣੀ; ਦਲੀ ਹੰਘਾਰ ਕੈ ॥", transliteration = "mangan naahee paanee; dlee hanghaar kai ||", translation = "Challenging the armies, these warriors do not even ask for water.", hindi = "मंगन नाही पाणी; दली हंघार कै ॥", punjabi = "(ਰਣ ਵਿਚ ਵੈਰੀ) ਦਲ ਨੂੰ ਲਲਕਾਰਦੇ ਹੋਏ (ਸੂਰਵੀਰ) ਪਾਣੀ ਤਕ ਨਹੀਂ ਮੰਗਦੇ ਸਨ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "chandi-di-vaar-143", gurmukhi = "ਜਣ ਕਰੀ ਸਮਾਇ ਪਠਾਣੀ; ਸੁਣਿ ਕੈ ਰਾਗ ਨੂੰ ॥", transliteration = "jan kree smaai pthaanee; sun kai raag noon ||", translation = "It seems that listening to the music, the Pathans have realized the state of ecstasy.", hindi = "जण करी समाइ पठाणी; सुणि कै राग नूं ॥", punjabi = "(ਉਹ ਯੁੱਧ ਵਿਚ ਇਤਨੇ ਮਗਨ ਸਨ) ਮਾਨੋ ਪਠਾਣ ਰਾਗ ਨੂੰ ਸੁਣ ਕੇ ਮਸਤ (ਸਮਾਇ) ਹੋ ਗਿਆ ਹੋਵੇ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "chandi-di-vaar-144", gurmukhi = "ਰਤੂ ਦੇ ਹੜਵਾਣੀ; ਚਲੇ ਬੀਰ ਖੇਤ ॥", transliteration = "ratoo de harvaanee; chle beer khet ||", translation = "The flood of the blood of the fighters is flowing.", hindi = "रतू दे हड़वाणी; चले बीर खेत ॥", punjabi = "ਰਣ-ਭੂਮੀ ਵਿਚ ਵੀਰ ਯੋਧਿਆਂ ਦੇ ਲਹੂ ਦਾ ਹੜ੍ਹ ਆ ਗਿਆ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "chandi-di-vaar-145", gurmukhi = "ਪੀਤਾ ਫੁਲੁ ਇਆਣੀ; ਘੁਮਨ ਸੂਰਮੇ ॥੨੦॥", transliteration = "peetaa phul iaanee; ghuman soorme ||20||", translation = "The brave warriors are roaming as if they have ignorantly consumed the intoxicating poppy.20.", hindi = "पीता फुलु इआणी; घुमन सूरमे ॥२०॥", punjabi = "ਇਆਣਾ (ਵਿਅਕਤੀ) ਫੁਲ ਪੀਣ ਤੇ (ਜਿਵੇਂ ਝੂਮਦਾ ਹੈ, ਉਸ ਤਰ੍ਹਾਂ) ਸੂਰਮੇ ਝੂਮ ਰਹੇ ਸਨ ॥੨੦॥", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "chandi-di-vaar-146", gurmukhi = "ਹੋਈ ਅਲੋਪ ਭਵਾਨੀ; ਦੇਵਾਂ ਨੂੰ ਰਾਜ ਦੇ ॥", transliteration = "hoee alop bhvaanee; devaan noon raaj de ||", translation = "Bhavani (Durga) disappeard after bestowing kingdom on the gods.", hindi = "होई अलोप भवानी; देवां नूं राज दे ॥", punjabi = "ਦੇਵਤਿਆਂ ਨੂੰ ਰਾਜ ਦੇ ਕੇ ਭਵਾਨੀ ਲੋਪ ਹੋ ਗਈ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "chandi-di-vaar-147", gurmukhi = "ਈਸਰ ਦੀ ਬਰਦਾਨੀ; ਹੋਈ ਜਿਤ ਦਿਨ ॥", transliteration = "eesar dee bardaanee; hoee jit din ||", translation = "The day for which Shiva granted the boon.", hindi = "ईसर दी बरदानी; होई जित दिन ॥", punjabi = "ਉਧਰ ਜਿਸ ਦਿਨ ਸ਼ਿਵ ਦੀ ਵਰਦਾਨੀ (ਘੜੀ) ਆ ਪਹੁੰਚੀ,", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "chandi-di-vaar-148", gurmukhi = "ਸੁੰਭ ਨਿਸੁੰਭ ਗੁਮਾਨੀ; ਜਨਮੇ ਸੂਰਮੇ ॥", transliteration = "sumbh nisumbh gumaanee; janme soorme ||", translation = "The proud warriors Sumbh and Nisumbh were born.", hindi = "सुंभ निसुंभ गुमानी; जनमे सूरमे ॥", punjabi = "ਤਦੋਂ ਸ਼ੁੰਭ-ਨਿਸ਼ੁੰਭ (ਨਾਂ ਦੇ) ਅਭਿਮਾਨੀ ਸੂਰਮੇ ਪੈਦਾ ਹੋ ਗਏ,", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "chandi-di-vaar-149", gurmukhi = "ਇੰਦ੍ਰ ਦੀ ਰਾਜਧਾਨੀ; ਤਕੀ ਜਿਤਨੀ ॥੨੧॥", transliteration = "indr dee raajdhaanee; tkee jitnee ||21||", translation = "They planned to conquer the capital of Indra.21.", hindi = "इंद्र दी राजधानी; तकी जितनी ॥२१॥", punjabi = "(ਜਿਨ੍ਹਾਂ ਨੇ) ਇੰਦਰ ਦੀ ਰਾਜਧਾਨੀ ਨੂੰ ਜਿਤਣ ਦੀ ਇੱਛਾ ਨਾਲ ਵੇਖਿਆ ॥੨੧॥", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "chandi-di-vaar-150", gurmukhi = "ਇੰਦ੍ਰਪੁਰੀ ਤੇ ਧਾਵਣਾ; ਵਡ ਜੋਧੀ ਮਤਾ ਪਕਾਇਆ ॥", transliteration = "indrapuree te dhaavnaa; vad jodhee mtaa pkaaiaa ||", translation = "The great fighters decided to rush towards the kingdom of Indra.", hindi = "इंद्रपुरी ते धावणा; वड जोधी मता पकाइआ ॥", punjabi = "ਵਡਿਆਂ (ਰਾਖਸ਼) ਯੋਧਿਆਂ ਨੇ ਇੰਦਰਪੁਰੀ ਉਤੇ ਹਮਲਾ ਕਰਨ ਦਾ ਵਿਚਾਰ ਕੀਤਾ (ਯੋਜਨਾ ਬਣਾਈ)।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "chandi-di-vaar-151", gurmukhi = "ਸੰਜ ਪਟੇਲਾ ਪਾਖਰਾ; ਭੇੜ ਸੰਦਾ ਸਾਜੁ ਬਣਾਇਆ ॥", transliteration = "sanj ptelaa paakhraa; bher sandaa saaj bnaaiaa ||", translation = "They began to prepare the war-material consisting of armour with belts and saddle-gear.", hindi = "संज पटेला पाखरा; भेड़ संदा साजु बणाइआ ॥", punjabi = "ਕਵਚ, ਪਟੇਲਾਂ (ਮੂੰਹ ਨੂੰ ਢਕਣ ਦੀ ਲੋਹੇ ਦੀ ਜਾਲੀ) ਅਤੇ ਪਾਖਰਾਂ (ਲੋਹੇ ਦੀ ਜਾਲੀ ਦੀਆਂ ਬਣੀਆਂ ਘੋੜਿਆਂ ਦੀਆਂ ਝੁਲਾਂ) (ਨੂੰ ਲੈ ਕੇ) ਲੜਾਈ ਦੀ ਤਿਆਰੀ ਸ਼ੁਰੂ ਕਰ ਦਿੱਤੀ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "chandi-di-vaar-152", gurmukhi = "ਜੰਮੇ ਕਟਕ ਅਛੂਹਣੀ; ਅਸਮਾਨੁ ਗਰਦੀ ਛਾਇਆ ॥", transliteration = "jamme katak achhoohnee; asmaan gardee chhaaiaa ||", translation = "An army of lakhs of warriors gathered and the dust rose to sky.", hindi = "जंमे कटक अछूहणी; असमानु गरदी छाइआ ॥", punjabi = "ਅਛੂਹਣੀ ਸੈਨਾ (ਇਕੱਠੀ ਹੋ ਕੇ) ਚਲ ਪਈ, (ਉਸ ਦੇ ਚਲਣ ਨਾਲ) ਘਟਾ ਨੇ ਆਕਾਸ਼ ਨੂੰ ਢਕ ਲਿਆ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "chandi-di-vaar-153", gurmukhi = "ਰੋਹ ਸੁੰਭ ਨਿਸੁੰਭ ਸਿਧਾਇਆ ॥੨੨॥", transliteration = "roh sumbh nisumbh sidhaaiaa ||22||", translation = "Sumbh and Nisumbh, full of rage, have marched forward.22.", hindi = "रोह सुंभ निसुंभ सिधाइआ ॥२२॥", punjabi = "ਰੋਹ ਨਾਲ ਭਰੇ ਹੋਏ ਸ਼ੁੰਭ ਅਤੇ ਨਿਸ਼ੁੰਭ (ਯੁੱਧ ਲਈ) ਤੁਰ ਪਏ ॥੨੨॥", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "chandi-di-vaar-154", gurmukhi = "ਪਉੜੀ ॥", transliteration = "pauree ||", translation = "PAURI", hindi = "पउड़ी ॥", punjabi = "ਪਉੜੀ:", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "chandi-di-vaar-155", gurmukhi = "ਸੁੰਭ ਨਿਸੁੰਭ ਅਲਾਇਆ; ਵਡ ਜੋਧੀ ਸੰਘਰੁ ਵਾਏ ॥", transliteration = "sumbh nisumbh alaaiaa; vad jodhee sanghar vaae ||", translation = "Sumbh and Nisumbh ordered the great warriors to sound the bugle of war.", hindi = "सुंभ निसुंभ अलाइआ; वड जोधी संघरु वाए ॥", punjabi = "ਸ਼ੁੰਭ ਅਤੇ ਨਿਸ਼ੁੰਭ ਨੇ ਆਦੇਸ਼ ਦਿੱਤਾ (ਤਾਂ) ਵੱਡੇ ਸੂਰਮਿਆਂ ਨੇ (ਯੁੱਧ ਦਾ) ਬਿਗਲ ਵਜਾ ਦਿੱਤਾ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "chandi-di-vaar-156", gurmukhi = "ਰੋਹ ਦਿਖਾਲੀ ਦਿਤੀਆ; ਵਰਿਆਮੀ ਤੁਰੇ ਨਚਾਏ ॥", transliteration = "roh dikhaalee diteeaa; vriaamee ture nchaae ||", translation = "Great fury was visulised and the brave fighters caused the horses to dance.", hindi = "रोह दिखाली दितीआ; वरिआमी तुरे नचाए ॥", punjabi = "(ਹਰ ਪਾਸੇ) ਰੋਹ ਦਾ ਵਾਤਾਵਰਨ ਬਣ ਗਿਆ ਅਤੇ ਸੂਰਵੀਰਾ ਨੇ ਘੋੜੇ ਨਚਾਉਣੇ ਸ਼ੁਰੂ ਕਰ ਦਿੱਤੇ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
