    BaniLine(id = "chandi-di-vaar-271", gurmukhi = "ਸਾਰਸੁਤੀ ਜਨੁ ਨਾਈਆਂ, ਮਿਲ ਕੈ ਦੇਵੀਆਂ ॥", transliteration = "saarsutee jan naaeeaan, mil kai deveeaan ||", translation = "It appeared that the goddesses gathering together, took their bath in river Saraswati.", hindi = "सारसुती जनु नाईआं, मिल कै देवीआं ॥", punjabi = "(ਇਉਂ ਪ੍ਰਤੀਤ ਹੁੰਦਾ ਹੈ) ਮਾਨੋ ਦੇਵੀਆਂ ਨੇ ਮਿਲ ਕੇ ਸਰਸਵਤੀ ਨਦੀ ਵਿਚ ਇਸ਼ਨਾਨ ਕੀਤਾ ਹੋਵੇ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
