    BaniLine(id = "chandi-di-vaar-365", gurmukhi = "ਟੋਪ ਪਟੇਲਾ ਪਾਖਰਾਂ, ਗਲਿ ਸੰਜ ਸਵਾਰੇ ॥", transliteration = "top ptelaa paakhraan, gal sanj svaare ||", translation = "They have bedecked themselves with helmets on their heads, and armour around their necks alongwith their horse-sddles with belts.", hindi = "टोप पटेला पाखरां, गलि संज सवारे ॥", punjabi = "ਅਤੇ (ਸਿਰਾਂ ਉਤੇ) ਟੋਪ, (ਮੂੰਹ ਤੇ) ਪਟੇਲ, (ਘੋੜੇ ਉਤੇ) ਪਾਖਰ ਅਤੇ ਗਲ ਵਿਚ ਕਵਚ ਪਾਏ ਹੋਏ ਸਨ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
