    BaniLine(id = "chandi-di-vaar-367", gurmukhi = "ਚੜੇ ਰਥੀ ਗਜ ਘੋੜਿਈ, ਮਾਰ ਭੁਇ ਤੇ ਡਾਰੇ ॥", transliteration = "chare rthee gaj ghoriee, maar bhui te daare ||", translation = "She killed and threw those on the round who were riding chariots, elephants and horses.", hindi = "चड़े रथी गज घोड़िई, मार भुइ ते डारे ॥", punjabi = "ਰਥਾਂ, ਹਾਥੀਆਂ ਅਤੇ ਘੋੜਿਆਂ ਉਪਰ ਚੜ੍ਹਿਆਂ ਹੋਇਆਂ ਨੂੰ ਮਾਰ ਕੇ ਧਰਤੀ ਉਤੇ ਸੁੱਟ ਦਿੱਤਾ ਸੀ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
