    BaniLine(id = "chandi-di-vaar-372", gurmukhi = "ਲਾਈ ਰਾਜੇ ਸੁੰਭ ਨੋ, ਰਤੁ ਪੀਐ ਪਿਆਰੀ ॥", transliteration = "laaee raaje sumbh no, rat peeai piaaree ||", translation = "She struck it on the king Sumbh and this lovely weapon drinks blood.", hindi = "लाई राजे सुंभ नो, रतु पीऐ पिआरी ॥", punjabi = "(ਉਹ) ਬਰਛੀ (ਦੇਵੀ ਨੇ) ਰਾਜੇ ਸ਼ੁੰਭ ਨੂੰ ਮਾਰ ਦਿੱਤੀ (ਜੋ) ਪਿਆਰੀ (ਉਸ ਦੇ) ਲਹੂ ਨੂੰ ਪੀ ਰਹੀ ਸੀ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "chandi-di-vaar-373", gurmukhi = "ਸੁੰਭ ਪਾਲਾਣੋ ਡਿਗਿਆ, ਉਪਮਾ ਬੀਚਾਰੀ ॥", transliteration = "sumbh paalaano digiaa, upmaa beechaaree ||", translation = "Sumbh fell down from the saddle for which the following simile hath been thought.", hindi = "सुंभ पालाणो डिगिआ, उपमा बीचारी ॥", punjabi = "ਸ਼ੁੰਭ ਕਾਠੀ ਤੋਂ ਡਿਗ ਪਿਆ, (ਉਹ ਦ੍ਰਿਸ਼ ਨੂੰ ਵੇਖ ਕੇ ਕਵੀ ਨੂੰ ਇੰਜ) ਉਪਮਾ ਸੁਝੀ", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
