    BaniLine(id = "chandi-di-vaar-379", gurmukhi = "ਸੁੰਭ ਨਿਸੁੰਭ ਸੰਘਾਰਿਆ ਵਥ ਜੇਹੇ ਸਾਹੀਂ ॥", transliteration = "sumbh nisumbh sanghaariaa vath jehe saaheen ||", translation = "She killed both Sumbh and Nisumbh, who were the masters of all the materials.", hindi = "सुंभ निसुंभ संघारिआ वथ जेहे साहीं ॥", punjabi = "ਸ਼ੁੰਭ ਨਿਸ਼ੁੰਭ ਵਰਗੇ ਨਾਮੀ ਯੋਧਿਆਂ ਨੂੰ ਮਾਰ ਸੁਟਿਆ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
