    BaniLine(id = "chandi-di-vaar-381", gurmukhi = "ਮੁਹਿ ਕੁੜੂਚੇ ਘਾਹ ਦੇ ਛਡ ਘੋੜੇ ਰਾਹੀਂ ॥", transliteration = "muh kurooche ghaah de chhad ghore raaheen ||", translation = "Accepting their defeat (by putting the straws of grass in their mouth), and leaving their horses in the way", hindi = "मुहि कुड़ूचे घाह दे छड घोड़े राहीं ॥", punjabi = "(ਬਹੁਤੇ ਦੈਂਤ) ਮੂੰਹ ਵਿਚ ਘਾਹ ਦੇ ਤੀਲੇ ਦੇ ਕੇ ਅਤੇ ਘੋੜਿਆਂ ਨੂੰ ਰਾਹ ਵਿਚ ਹੀ ਛਡ ਕੇ (ਦੇਵੀ ਦੇ ਸਾਹਮਣੇ ਆਪਣੀ ਅਸਮਰਥਾ ਪ੍ਰਗਟ ਕਰਨ ਲਗੇ)।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "chandi-di-vaar-382", gurmukhi = "ਭਜਦੇ ਹੋਏ ਮਾਰੀਅਨ ਮੁੜ ਝਾਕਨ ਨਾਹੀਂ ॥੫੪॥", transliteration = "bhajde hoe maareean mur jhaakan naaheen ||54||", translation = "They are being killed, while fleeing, without looking back.54.", hindi = "भजदे होए मारीअन मुड़ झाकन नाहीं ॥५४॥", punjabi = "ਭਜਦੇ ਜਾਂਦੇ ਦੈਂਤ ਵੀ (ਦੇਵੀ ਦੁਆਰਾ ਮਾਰੇ ਜਾ ਰਹੇ ਸਨ, (ਪਰ ਉਹ) ਪਿਛੇ ਮੁੜ ਕੇ ਝਾਕਦੇ ਤਕ ਨਹੀਂ ਸਨ ॥੫੪॥", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
