    BaniLine(id = "chandi-di-vaar-384", gurmukhi = "ਸੁੰਭ ਨਿਸੁੰਭ ਪਠਾਇਆ, ਜਮ ਦੇ ਧਾਮ ਨੋ ॥", transliteration = "sumbh nisumbh pthaaiaa, jam de dhaam no ||", translation = "Sumbh and Nisumbh were dispatched to the abode of Yama", hindi = "सुंभ निसुंभ पठाइआ, जम दे धाम नो ॥", punjabi = "(ਦੇਵੀ ਨੇ) ਸ਼ੁੰਭ ਅਤੇ ਨਿਸ਼ੁੰਭ ਨੂੰ ਯਮ-ਲੋਕ ਨੂੰ ਤੋਰ ਦਿੱਤਾ", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L)
